/**
 * @param {number[]} arr
 * @return {number}
 */
var numFactoredBinaryTrees = function(arr) {
    const MOD = 1000000007n;
    arr.sort((a, b) => a - b);
    const dp = new Map();
    const set = new Set(arr);
    let total = 0n;
    for (let i = 0; i < arr.length; i++) {
        let count = 1n;
        for (let j = 0; j < i; j++) {
            if (arr[i] % arr[j] === 0) {
                const other = arr[i] / arr[j];
                if (set.has(other)) {
                    count = (count + dp.get(arr[j]) * dp.get(other)) % MOD;
                }
            }
        }
        dp.set(arr[i], count);
        total = (total + count) % MOD;
    }
    return Number(total);
};
