/**
 * @param {number} n
 * @return {number}
 */
var clumsy = function(n) {
    const stack = [n];
    let op = 0;
    for (let i = n - 1; i >= 1; i--) {
        if (op === 0) {
            stack.push(stack.pop() * i);
        } else if (op === 1) {
            let top = stack.pop();
            stack.push(Math.trunc(top / i));
        } else if (op === 2) {
            stack.push(i);
        } else {
            stack.push(-i);
        }
        op = (op + 1) % 4;
    }
    let sum = 0;
    for (const v of stack) sum += v;
    return sum;
};
