Use a Fenwick tree over value range (1..1e5) with count and sum, plus a queue of last m elements.

```javascript
/**
 * @param {number} m
 * @param {number} k
 */
var MKAverage = function(m, k) {
    this.m = m;
    this.k = k;
    this.queue = [];
    this.MAX = 100001;
    this.cnt = new Array(this.MAX + 1).fill(0);
    this.sum = new Array(this.MAX + 1).fill(0);
    this.total = 0; // total count in tree
    this.totalSum = 0;
};

MKAverage.prototype._update = function(i, dc, ds) {
    for (; i <= this.MAX; i += i & (-i)) {
        this.cnt[i] += dc;
        this.sum[i] += ds;
    }
};

// returns {cnt, sum} of values <= i
MKAverage.prototype._query = function(i) {
    let c = 0, s = 0;
    for (; i > 0; i -= i & (-i)) {
        c += this.cnt[i];
        s += this.sum[i];
    }
    return [c, s];
};

// find smallest value v such that prefix count >= target
MKAverage.prototype._kth = function(target) {
    let pos = 0;
    let c = 0;
    let LOG = 17;
    for (let pw = 1 << LOG; pw > 0; pw >>= 1) {
        let next = pos + pw;
        if (next <= this.MAX && c + this.cnt[next] < target) {
            pos = next;
            c += this.cnt[next];
        }
    }
    return pos + 1;
};

/** 
 * @param {number} num
 * @return {void}
 */
MKAverage.prototype.addElement = function(num) {
    this.queue.push(num);
    this._update(num, 1, num);
    this.total++;
    this.totalSum += num;
    if (this.queue.length > this.m) {
        let old = this.queue.shift();
        this._update(old, -1, -old);
        this.total--;
        this.totalSum -= old;
    }
};

/**
 * @return {number}
 */
MKAverage.prototype.calculateMKAverage = function() {
    if (this.queue.length < this.m) return -1;
    // remove smallest k and largest k
    // sum of smallest k:
    let k = this.k;
    // find the value at position k (kth smallest)
    let vk = this._kth(k);
    let [ck, sk] = this._query(vk);
    // sum of smallest k: we have ck elements <= vk, ck >= k
    // sum including vk occurrences; need exactly k smallest
    let smallSum;
    {
        // elements strictly below vk
        let below = this._query(vk - 1);
        let belowCnt = below[0], belowSum = below[1];
        let need = k - belowCnt; // occurrences of vk to include
        smallSum = belowSum + need * vk;
    }
    // largest k: position total-k+1 .. total
    let m = this.m;
    let vk2 = this._kth(m - k + 1); // value at position m-k+1 (first of largest k)
    let largeSum;
    {
        // elements strictly above vk2
        let below2 = this._query(vk2); // count <= vk2
        let aboveCnt = this.total - below2[0];
        let aboveSum = this.totalSum - below2[1];
        let need = k - aboveCnt; // occurrences of vk2 to include in largest
        largeSum = aboveSum + need * vk2;
    }
    let middleSum = this.totalSum - smallSum - largeSum;
    let middleCnt = m - 2 * k;
    return Math.floor(middleSum / middleCnt);
};
```

trace.prompt:
Solve this LeetCode problem `finding-mk-average` in JavaScript.

You are given two integers, `m` and `k`, and a stream of integers. You are tasked to implement a data structure that calculates the **MKAverage** for the stream.

The **MKAverage** can be calculated using these steps:

1.  If the number of the elements in the stream is less than `m` you should consider the **MKAverage** to be `-1`. Otherwise, copy the last `m` elements of the stream to a separate container.
2.  Remove the smallest `k` elements and the largest `k` elements from the container.
3.  Calculate the average value for the rest of the elements **rounded down to the nearest integer**.

Implement the `MKAverage` class:

*   `MKAverage(int m, int k)` Initializes the **MKAverage** object with an empty stream and the two integers `m` and `k`.
*   `void addElement(int num)` Inserts a new element `num` into the stream.
*   `int calculateMKAverage()` Calculates and returns the **MKAverage** for the current stream **rounded down to the nearest integer**.

**Example 1:**

**Input**
\[ "MKAverage ",  "addElement ",  "addElement ",  "calculateMKAverage ",  "addElement ",  "calculateMKAverage ",  "addElement ",  "addElement ",  "addElement ",  "calculateMKAverage "\]
\[\[3, 1\], \[3\], \[1\], \[\], \[10\], \[\], \[5\], \[5\], \[5\], \[\]\]
**Output**
