var maximumANDSum = function(nums, numSlots) {
    const pow3 = [1];
    for (let i = 1; i <= numSlots; i++) pow3[i] = pow3[i-1]*3;
    const total = pow3[numSlots];
    const dp = new Int32Array(total).fill(-1);
    dp[0] = 0;
    let idx = 0;
    let ans = 0;
    for (let mask = 0; mask < total; mask++) {
        if (dp[mask] < 0) continue;
        // count placed numbers
        let placed = 0;
        for (let s = 0; s < numSlots; s++) {
            placed += Math.floor(mask / pow3[s]) % 3;
        }
        if (placed >= nums.length) {
            ans = Math.max(ans, dp[mask]);
            continue;
        }
        const num = nums[placed];
        for (let s = 0; s < numSlots; s++) {
            const cnt = Math.floor(mask / pow3[s]) % 3;
            if (cnt < 2) {
                const nmask = mask + pow3[s];
                const val = dp[mask] + (num & (s+1));
                if (val > dp[nmask]) dp[nmask] = val;
            }
        }
    }
    return ans;
};
