 * @param {number} maxTime
 * @param {number[][]} edges
 * @param {number[]} passingFees
 * @return {number}
 */
var minCost = function(maxTime, edges, passingFees) {
    const n = passingFees.length;
    const INF = Infinity;
    // dp[t][node] = min cost to reach node using exactly time t
    // We use dp over time, dp[node] best cost at time <= t
    // dp2[node][t] min cost
    const dp = Array.from({length: maxTime + 1}, () => new Array(n).fill(INF));
    dp[0][0] = passingFees[0];
    let ans = INF;
    for (let t = 0; t <= maxTime; t++) {
        for (let i = 0; i < edges.length; i++) {
            const [x, y, time] = edges[i];
            if (t + time <= maxTime) {
                if (dp[t][x] !== INF) {
                    const nc = dp[t][x] + passingFees[y];
                    if (nc < dp[t + time][y]) dp[t + time][y] = nc;
                }
                if (dp[t][y] !== INF) {
                    const nc = dp[t][y] + passingFees[x];
                    if (nc < dp[t + time][x]) dp[t + time][x] = nc;
                }
            }
        }
    }
    for (let t = 0; t <= maxTime; t++) {
        if (dp[t][n - 1] < ans) ans = dp[t][n - 1];
    }
    return ans === INF ? -1 : ans;
};
