var numOfWays = function(nums) {
    const MOD = 1000000007n;
    const n = nums.length;

    // precompute factorials and inverse factorials mod MOD
    const fact = new Array(n + 1);
    const invFact = new Array(n + 1);
    fact[0] = 1n;
    for (let i = 1; i <= n; i++) fact[i] = (fact[i-1] * BigInt(i)) % MOD;

    const modpow = (b, e, m) => {
        let r = 1n;
        b %= m;
        while (e > 0n) {
            if (e & 1n) r = (r * b) % m;
            b = (b * b) % m;
            e >>= 1n;
        }
        return r;
    };

    invFact[n] = modpow(fact[n], MOD - 2n, MOD);
    for (let i = n; i > 0; i--) invFact[i-1] = (invFact[i] * BigInt(i)) % MOD;

    const comb = (a, b) => {
        if (b < 0 || b > a) return 0n;
        return (fact[a] * invFact[b] % MOD) * invFact[a-b] % MOD;
    };

    const count = (arr) => {
        const m = arr.length;
        if (m <= 2) return 1n;
        const root = arr[0];
        const left = [], right = [];
        for (let i = 1; i < m; i++) {
            if (arr[i] < root) left.push(arr[i]);
            else right.push(arr[i]);
        }
        const l = count(left);
        const r = count(right);
        return comb(m - 1, left.length) * l % MOD * r % MOD;
    };

    const result = (count(nums) - 1n + MOD) % MOD;
    return Number(result);
};
