    if (m * k > n) return -1;

    let lo = Math.min(...bloomDay);
    let hi = Math.max(...bloomDay);

    const canMake = (day) => {
        let bouquets = 0, adjacent = 0;
        for (let i = 0; i < n; i++) {
            if (bloomDay[i] <= day) {
                adjacent++;
                if (adjacent === k) {
                    bouquets++;
                    adjacent = 0;
                }
            } else {
                adjacent = 0;
            }
        }
        return bouquets >= m;
    };

    while (lo < hi) {
        const mid = Math.floor((lo + hi) / 2);
        if (canMake(mid)) {
            hi = mid;
        } else {
            lo = mid + 1;
        }
    }

    return lo;
