/**
 * @param {number[]} tasks
 * @param {number} sessionTime
 * @return {number}
 */
var minSessions = function(tasks, sessionTime) {
    const n = tasks.length;
    const full = (1 << n) - 1;
    // sum[mask] = total time of tasks in mask
    const sum = new Array(1 << n).fill(0);
    for (let mask = 1; mask <= full; mask++) {
        const low = mask & (-mask);
        const idx = Math.log2(low);
        sum[mask] = sum[mask ^ low] + tasks[idx];
    }
    // dp[mask] = min sessions to finish tasks in mask
    const dp = new Array(1 << n).fill(Infinity);
    dp[0] = 0;
    for (let mask = 1; mask <= full; mask++) {
        // iterate over submasks that form one session (fit in sessionTime)
        for (let sub = mask; sub > 0; sub = (sub - 1) & mask) {
            if (sum[sub] <= sessionTime) {
                dp[mask] = Math.min(dp[mask], dp[mask ^ sub] + 1);
            }
        }
    }
    return dp[full];
};
